// deploy/cyrus/nginx-cyrus-my.conf (prepared, applied by the owner): pins the explicit public-file list and the app-path regex.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";

const ROOT = path.join(import.meta.dirname, "..");
const conf = readFileSync(path.join(ROOT, "deploy/cyrus/nginx-cyrus-my.conf"), "utf8");
const patch = readFileSync(path.join(ROOT, "deploy/cyrus/nginx-cyrus-my.conf.patch"), "utf8");

describe("cyrus.my vhost (rc10)", () => {
  it("proxies every app prefix the launch check requires", async () => {
    const m = (await import(path.join(ROOT, "scripts/cyrus/lib/launch-eval.mjs"))) as { nginxAppPrefixes: (c: string) => string[]; REQUIRED_APP_PREFIXES: string[] };
    const got = m.nginxAppPrefixes(conf);
    for (const p of m.REQUIRED_APP_PREFIXES) assert.ok(got.includes(p), `missing app prefix ${p}`);
  });
  it("has no try_files catch-all to the app and ends in an explicit deny", () => {
    assert.ok(!/location\s+\/\s*\{\s*try_files/.test(conf));
    assert.ok(!conf.includes("@cyrus_app"));
    assert.match(conf, /location \/ \{ add_header X-Cyrus-Edge denied always; return 404; \}/);
  });
  it("keeps the landing files static and /assets/ carved out of the app regex", () => {
    assert.match(conf, /location \^~ \/assets\/ \{ try_files \$uri =404;/);
    assert.match(conf, /location = \/ \{ try_files \/index\.html =404; \}/);
  });
  it("keeps the auth rate limit and the pack block", () => {
    assert.match(conf, /limit_req zone=nxeon_auth burst=15 nodelay;/);
    assert.match(conf, /location ~ "\^\/packs\/p\/\(\[0-9a-f\]\{40\}\)\\\.zip\$"/);
  });
  it("the patch removes the catch-all and adds the new paths", () => {
    assert.match(patch, /^-\s+location \/ \{ try_files \$uri \$uri\/ @cyrus_app; \}/m);
    assert.match(patch, /^\+.*api\/log/m);
  });
});
EOF
