// scripts/cyrus/lib/eval-run.mjs + the launch-check rows built from it (live eval verdict without a gate.json).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const ROOT = path.join(import.meta.dirname, "..");
type Run = { tag: string; complete: boolean; planned: number; done: number; builds: number; passAt1Pct: number | null; finalPassPct: number | null; bootPct: number | null; repairSharePct: number | null; failing: { job: string }[] };
type Lib = { latestRuns: (d: string) => { completed: Run | null; inProgress: Run | null }; summarizeResults: (r: unknown[]) => Run };
const lib = () => import(path.join(ROOT, "scripts/cyrus/lib/eval-run.mjs")) as Promise<Lib>;

const done = (job: string, o: Record<string, unknown> = {}) => JSON.stringify({ t: "done", job, result: { job, lane: "plain", pass: true, firstAttempt: true, repairs: 0, costUsd: 0.1, flight: { verdict: "passed" }, ...o } });
function run(dir: string, tag: string, jobs: string[], lines: string[], extra: Record<string, string> = {}) {
  mkdirSync(path.join(dir, tag), { recursive: true });
  writeFileSync(path.join(dir, tag, "journal.jsonl"), [JSON.stringify({ t: "plan", tag, model: "saka", jobs }), ...lines].join("\n") + "\n");
  for (const [f, c] of Object.entries(extra)) writeFileSync(path.join(dir, tag, f), c);
}

describe("eval-run lib", () => {
  it("summarises pass@1, final pass, boot and repair share; infra builds are excluded", async () => {
    const m = await lib();
    const s = m.summarizeResults([
      JSON.parse(done("a")).result, JSON.parse(done("b", { firstAttempt: false, repairs: 1, costUsd: 0.3 })).result,
      JSON.parse(done("c", { pass: false, firstAttempt: false, flight: { verdict: "failed" }, status: "failed" })).result, JSON.parse(done("d", { infra: true })).result,
    ]);
    assert.equal(s.builds, 3);
    assert.equal(s.passAt1Pct, 33.3);
    assert.equal(s.finalPassPct, 66.7);
    assert.equal(s.bootPct, 100);
    assert.equal(s.repairSharePct, 50);
    assert.deepEqual(s.failing.map((x) => x.job), ["c"]);
  });
  it("picks the newest completed run and reports an unfinished one separately", async () => {
    const m = await lib();
    const dir = mkdtempSync(path.join(tmpdir(), "evr-"));
    run(dir, "first1", ["a", "b"], [done("a"), done("b")]);
    run(dir, "second1", ["a", "b", "c"], [done("a"), done("b")]);
    const r = m.latestRuns(dir);
    assert.equal(r.completed?.tag, "first1");
    assert.equal(r.inProgress?.tag, "second1");
    assert.equal(r.inProgress?.done, 2);
    assert.equal(r.inProgress?.planned, 3);
  });
  it("a budget stop or a report file marks a run complete; a missing dir is empty", async () => {
    const m = await lib();
    const dir = mkdtempSync(path.join(tmpdir(), "evr-"));
    run(dir, "x1", ["a", "b"], [done("a"), JSON.stringify({ t: "budget_stop" })]);
    run(dir, "x2", ["a", "b"], [done("a")], { "report.md": "r" });
    const r = m.latestRuns(dir);
    assert.ok(r.completed);
    assert.equal(r.inProgress, null);
    assert.deepEqual(m.latestRuns(path.join(dir, "nope")), { completed: null, inProgress: null });
  });
});

describe("launch-eval eval-run row", () => {
  it("fails on a low final pass and warns with no completed run", async () => {
    const ev = (await import(path.join(ROOT, "scripts/cyrus/lib/launch-eval.mjs"))) as { evaluate: (f: unknown) => { id: string; beta: string; public: string; detail: string }[] };
    const now = "2026-10-14T12:00:00.000Z";
    const base = { now, eval: { at: null, baselineExists: true } };
    const get = (f: unknown, id: string) => ev.evaluate(f).find((r) => r.id === id);
    assert.equal(get({ ...base, evalRuns: { completed: null, inProgress: null } }, "eval-run")?.beta, "WARN");
    const c = { tag: "t1", at: now, builds: 10, passAt1Pct: 80, finalPassPct: 80, bootPct: 100, repairSharePct: 10, costUsd: 3, failing: [{ job: "x" }] };
    const row = get({ ...base, evalRuns: { completed: c, inProgress: { tag: "t2", done: 3, planned: 9, passAt1Pct: 100, finalPassPct: 100, bootPct: 100, costUsd: 1 } } }, "eval-run");
    assert.equal(row?.public, "FAIL");
    assert.match(row?.detail ?? "", /t1: 10 builds, pass@1 80%/);
    assert.equal(get({ ...base, evalRuns: { completed: { ...c, finalPassPct: 98, failing: [] }, inProgress: null } }, "eval-run")?.public, "PASS");
  });
});
EOF
