      JSON.parse(done("a")).result, JSON.parse(done("b", { firstAttempt: false, repairs: 1, costUsd: 0.3 })).result,
      JSON.parse(done("c", { pass: false, firstAttempt: false, flight: { verdict: "failed" }, status: "failed" })).result, JSON.parse(done("d", { infra: true })).result,
    ]);
    assert.equal(s.builds, 3);
    assert.equal(s.passAt1Pct, 33.3);
    assert.equal(s.finalPassPct, 66.7);
    assert.equal(s.bootPct, 100);
    assert.equal(s.repairSharePct, 50);
    assert.deepEqual(s.failing.map((x) => x.job), ["c"]);
  });
  it("picks the newest completed run and reports an unfinished one separately", async () => {
    const m = await lib();
    const dir = mkdtempSync(path.join(tmpdir(), "evr-"));
    run(dir, "first1", ["a", "b"], [done("a"), done("b")]);
    run(dir, "second1", ["a", "b", "c"], [done("a"), done("b")]);
    const r = m.latestRuns(dir);
    assert.equal(r.completed?.tag, "first1");
    assert.equal(r.inProgress?.tag, "second1");
    assert.equal(r.inProgress?.done, 2);
    assert.equal(r.inProgress?.planned, 3);
  });
  it("a budget stop or a report file marks a run complete; a missing dir is empty", async () => {
    const m = await lib();
    const dir = mkdtempSync(path.join(tmpdir(), "evr-"));
    run(dir, "x1", ["a", "b"], [done("a"), JSON.stringify({ t: "budget_stop" })]);
    run(dir, "x2", ["a", "b"], [done("a")], { "report.md": "r" });
    const r = m.latestRuns(dir);
    assert.ok(r.completed);
    assert.equal(r.inProgress, null);
    assert.deepEqual(m.latestRuns(path.join(dir, "nope")), { completed: null, inProgress: null });
  });
});

