cd /tank/dev-worktrees/cyrus-rc10 && cat > test/modbuilder-rc10-fixes.test.ts <<'EOF'
// rc10 quality fixes, each from a class seen in the live evals (fourth1 on image 0.16, third1, second1):
//  1. leftover-drop perf guard never ran in the FIRST round (rec.perf is set by PERF.inject inside compile(), after autofix)
//  2. `private boolean onCommand(...)` -> "attempting to assign weaker access privileges; was public"
//  3. `List<Entity> x = world.getNearbyEntities(...)` -> Collection cannot be converted to List
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/* eslint-disable @typescript-eslint/no-require-imports, @typescript-eslint/no-explicit-any */
const AF = require("../services/modbuilder/autofix.js") as any;
const PERF = require("../services/modbuilder/perf.js") as any;
const ROOT = path.join(import.meta.dirname, "..");

function ws(files: Record<string, string>) {
  const d = fs.mkdtempSync(path.join(os.tmpdir(), "mb-rc10-"));
  for (const [rel, text] of Object.entries(files)) { fs.mkdirSync(path.dirname(path.join(d, rel)), { recursive: true }); fs.writeFileSync(path.join(d, rel), text); }
  return d;
}
const rel = "src/main/java/dev/nxeon/plugins/demo/Cmd.java";

describe("rc10: perf guard in the first round", () => {
  it("perfPackageOf derives <main package>.nxperf from plugin.yml before the watchdog is injected", () => {
    const d = ws({ "src/main/resources/plugin.yml": "name: Demo\nmain: dev.nxeon.plugins.demo.DemoPlugin\nversion: 1.0\n" });
    assert.equal(PERF.perfPackageOf(d), "dev.nxeon.plugins.demo.nxperf");
    assert.equal(PERF.perfPackageOf(ws({})), null);
  });
  it("the package derived without injection equals the one inject() uses", () => {
    const d = ws({ "src/main/resources/plugin.yml": "name: Demo\nmain: dev.nxeon.plugins.demo.DemoPlugin\n", "src/main/java/dev/nxeon/plugins/demo/DemoPlugin.java": "package dev.nxeon.plugins.demo;\npublic class DemoPlugin extends org.bukkit.plugin.java.JavaPlugin {\n public void onEnable() {}\n}\n" });
    const before = PERF.perfPackageOf(d);
    const r = PERF.inject(d, {});
    assert.equal(r.pkg, before);
  });
  it("server.js runs fixPerf with the derived package when rec.perf is not set yet", () => {
    const s = fs.readFileSync(path.join(ROOT, "services/modbuilder/server.js"), "utf8");
    assert.match(s, /const perfPkg = \(rec\.perf && rec\.perf\.pkg\) \|\| PERF\.perfPackageOf\(ws\);/);
    assert.match(s, /AF\.fixPerf\(srcs, perfPkg\)/);
  });
  it("end to end on a fresh workspace: guard added, pre-check clean, no model turn needed", () => {
    const src = "package dev.nxeon.plugins.demo;\nimport org.bukkit.entity.Player;\nimport org.bukkit.inventory.ItemStack;\nimport java.util.*;\nclass Cmd {\n  void give(Player target, ItemStack item) {\n    Map<Integer, ItemStack> leftover = target.getInventory().addItem(item);\n    for (ItemStack extra : leftover.values()) {\n        target.getWorld().dropItemNaturally(target.getLocation(), extra);\n    }\n  }\n}\n";
    const d = ws({ "src/main/resources/plugin.yml": "name: Demo\nmain: dev.nxeon.plugins.demo.DemoPlugin\n", [rel]: src });
    const f = [{ rel, abs: path.join(d, rel) }];
    assert.equal(PERF.perfcheck(f).length, 1);
    const fx = AF.fixPerf(f, PERF.perfPackageOf(d)).fixes;
    assert.ok(fx.some((x: any) => x.kind === "perf-spawn-guard"));
    assert.equal(PERF.perfcheck(f).length, 0);
  });
});

describe("rc10: mechanical compile fixes", () => {
  const OUT = (line: number, sig: string, code: string, was = "public") => `${rel}:${line}: error: ${sig} in Demo cannot implement ${sig} in CommandExecutor\n${code}\n${" ".repeat(20)}^\n  attempting to assign weaker access privileges; was ${was}\n1 error\n`;
  it("private onCommand becomes public", () => {
    const code = "    private boolean onCommand(CommandSender s, Command c, String l, String[] a) {";
    const d = ws({ [rel]: `class Demo {\n${code}\n return true;\n}\n}\n` });
    const r = AF.fixWeakerAccess(OUT(2, "onCommand(CommandSender,Command,String,String[])", code), d);
    assert.equal(r.fixes.length, 1);
    assert.match(fs.readFileSync(path.join(d, rel), "utf8"), /^    public boolean onCommand\(/m);
  });
  it("package-private and protected implementations get the required modifier; fields/statics/unknown lines are left alone", () => {
    const d = ws({ [rel]: "class Demo {\n    boolean onCommand(CommandSender s, Command c, String l, String[] a) {\n    }\n    protected List<String> onTabComplete(CommandSender s, Command c, String l, String[] a) {\n    }\n    private static boolean x(int a) {\n    }\n    int q = 1;\n}\n" });
    const o = (n: number, code: string) => OUT(n, "m()", code);
    assert.equal(AF.fixWeakerAccess(o(2, ""), d).fixes.length, 1);
    assert.equal(AF.fixWeakerAccess(o(4, ""), d).fixes.length, 1);
    assert.equal(AF.fixWeakerAccess(o(6, ""), d).fixes.length, 0); // static
    assert.equal(AF.fixWeakerAccess(o(8, ""), d).fixes.length, 0); // not a method
    const t = fs.readFileSync(path.join(d, rel), "utf8");
    assert.match(t, /^    public boolean onCommand\(/m);
    assert.match(t, /^    public List<String> onTabComplete\(/m);
  });
  it("fixCompile wires both new fixes", () => {
    const code = "    private boolean onCommand(CommandSender s, Command c, String l, String[] a) {";
    const d = ws({ [rel]: `class Demo {\n${code}\n}\n}\n` });
    const r = AF.fixCompile(OUT(2, "onCommand(CommandSender,Command,String,String[])", code), d, "1.21.11", { classIndex: () => new Map(), members: () => null });
    assert.deepEqual(r.fixes.map((f: any) => f.kind), ["weaker-access"]);
  });
  it("Collection assigned to List is copied into an ArrayList (single-line declarations only)", () => {
    const d = ws({ [rel]: "class Demo {\n void f() {\n  List<Entity> near = world.getNearbyEntities(loc, 5, 5, 5);\n  List<Entity> a =\n   world.getNearbyEntities(loc, 1, 1, 1);\n }\n}\n" });
    const out = (n: number) => `${rel}:${n}: error: incompatible types: Collection<Entity> cannot be converted to List<Entity>\n`;
    assert.equal(AF.fixCollectionToList(out(3), d).fixes.length, 1);
    assert.equal(AF.fixCollectionToList(out(4), d).fixes.length, 0);
    assert.match(fs.readFileSync(path.join(d, rel), "utf8"), /List<Entity> near = new java\.util\.ArrayList<>\(world\.getNearbyEntities\(loc, 5, 5, 5\)\);/);
  });
});
EOF
