import { NextResponse } from "next/server";
import type Stripe from "stripe";
import { getHost } from "@/lib/cyrus/host";
import { handleStorageStripeEvent } from "@/lib/cyrus/storage/addon";
import { storageAddonsEnabled } from "@/lib/cyrus/storage/config";

export const dynamic = "force-dynamic";

/**
 * r51: the card checkout's return leg for a storage add-on. Runs the SAME idempotent apply the webhook runs (invoice.paid
 * by the subscription's first invoice, idemKey stripe:<invoice>), then sends the customer to Account, Storage. 404 while
 * CYRUS_STORAGE_ADDONS is off.
 */
export async function GET(req: Request) {
  if (!storageAddonsEnabled()) return new Response("Not found.", { status: 404 });
  const id = new URL(req.url).searchParams.get("session_id") ?? "";
  const s = getHost().billing.stripe;
  if (/^cs_[A-Za-z0-9_]{8,200}$/.test(id) && s?.configured()) {
    try {
      const session = await s.client().checkout.sessions.retrieve(id, { expand: ["subscription"] }, s.requestOptions);
      const sub = session.subscription as Stripe.Subscription | null;
      const inv = typeof sub?.latest_invoice === "string" ? sub.latest_invoice : sub?.latest_invoice?.id;
      if (session.metadata?.cyrusKind === "storage" && inv) await handleStorageStripeEvent({ type: "invoice.paid", data: { object: { id: inv } } } as unknown as Stripe.Event);
    } catch (e) {
      console.error("[cyrus-storage] return", (e as Error).message); // the webhook applies it anyway
    }
  }
  return NextResponse.redirect(new URL("/dashboard/cyrus/app/account?tab=storage", req.url), 303);
}
import { test } from "node:test";
import assert from "node:assert/strict";
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { appOrigin, requestOrigin } from "../lib/public-origin";

const req = (h: Record<string, string>) => ({ headers: { get: (n: string) => h[n.toLowerCase()] ?? null } });

test("appOrigin defaults to the production site and strips a trailing slash", () => {
  const prev = process.env.APP_URL;
  try {
    delete process.env.APP_URL;
    assert.equal(appOrigin(), "https://nxeon.cloud");
    process.env.APP_URL = "https://example.test///";
    assert.equal(appOrigin(), "https://example.test");
  } finally { if (prev === undefined) delete process.env.APP_URL; else process.env.APP_URL = prev; }
});

test("requestOrigin never returns the internal bind address", () => {
  const prev = process.env.APP_URL; process.env.APP_URL = "https://nxeon.cloud";
  try {
    assert.equal(requestOrigin(req({ host: "0.0.0.0:3000" })), "https://nxeon.cloud");
    assert.equal(requestOrigin(req({ host: "localhost:3000", "x-forwarded-host": "127.0.0.1:3000" })), "https://nxeon.cloud");
    assert.equal(requestOrigin(req({})), "https://nxeon.cloud");
    assert.equal(requestOrigin(req({ "x-forwarded-host": "trynxeon.com", "x-forwarded-proto": "https" })), "https://trynxeon.com");
    assert.equal(requestOrigin(req({ host: "evil.com/\\@x" })), "https://nxeon.cloud");
  } finally { if (prev === undefined) delete process.env.APP_URL; else process.env.APP_URL = prev; }
});

function routeFiles(dir: string, out: string[] = []): string[] {
  for (const e of readdirSync(dir)) {
    const p = join(dir, e);
    if (statSync(p).isDirectory()) { if (e !== "node_modules") routeFiles(p, out); }
    else if (/^route\.tsx?$/.test(e)) out.push(p);
  }
  return out;
}

test("no route handler redirects against req.nextUrl.origin or req.url (0.0.0.0:3000 behind nginx)", () => {
  const bad: string[] = [];
  for (const f of routeFiles(join(__dirname, "..", "app"))) {
    const src = readFileSync(f, "utf8");
    for (const m of src.matchAll(/new URL\(([^)]*?),\s*(req(?:uest)?\.nextUrl\.origin|req(?:uest)?\.url)\s*\)/g)) {
      // a `new URL(req.url)` PARSE is fine; only building a destination from the request origin is the bug.
      if (/redirect\(/.test(src)) bad.push(`${f}: ${m[0]}`);
    }
  }
  assert.deepEqual(bad, []);
});

