/**
 * The origin to build redirects against from a route handler.
 *
 * `req.nextUrl.origin` / `new URL(path, req.url)` are WRONG in production: the standalone server binds to
 * 0.0.0.0:3000 behind nginx, so they yield `https://0.0.0.0:3000/...` and the visitor lands on a browser
 * error page (found 2026-10-04: every email-verification link ended on ERR_ADDRESS_INVALID, the account
 * was verified but the customer saw an error). Use these helpers instead.
 */

/** The platform's own public origin (APP_URL, no trailing slash), defaulting to the production site. */
export function appOrigin(): string {
  return (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");
}

const INTERNAL_HOST = /^(0\.0\.0\.0|127\.0\.0\.1|localhost|\[::1?\])(:\d+)?$/i;

/**
 * The origin the visitor actually used (so a contact form on a different marketing host stays on that host),
 * taken from nginx's forwarded headers; falls back to APP_URL when the headers are missing or internal.
 */
export function requestOrigin(req: { headers: { get(name: string): string | null } }): string {
  const host = (req.headers.get("x-forwarded-host") ?? req.headers.get("host") ?? "").split(",")[0].trim();
  if (!host || INTERNAL_HOST.test(host) || /[\s/\\@]/.test(host)) return appOrigin();
  const proto = (req.headers.get("x-forwarded-proto") ?? "https").split(",")[0].trim().toLowerCase();
  return `${proto === "http" ? "http" : "https"}://${host}`;
}

